import sys
import math

def build_lca_tree(n, edges):
    parent = [-1] * n
    depth = [0] * n
    adj = [[] for _ in range(n)]

    for u, v in edges:
        u -= 1
        v -= 1
        adj[u].append(v)
        adj[v].append(u)

    def dfs(node, par, d):
        parent[node] = par
        depth[node] = d
        for child in adj[node]:
            if child != par:
                dfs(child, node, d + 1)

    dfs(0, -1, 0)

    max_log = int(math.log2(n)) + 1
    lca = [[-1] * max_log for _ in range(n)]

    for i in range(n):
        lca[i][0] = parent[i]

    for j in range(1, max_log):
        for i in range(n):
            if lca[i][j - 1] != -1:
                lca[i][j] = lca[lca[i][j - 1]][j - 1]

    def get_lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u

        diff = depth[u] - depth[v]
        for j in range(max_log):
            if (diff >> j) & 1:
                u = lca[u][j]

        if u == v:
            return u

        for j in range(max_log - 1, -1, -1):
            if lca[u][j] != lca[v][j]:
                u = lca[u][j]
                v = lca[v][j]

        return lca[u][0]

    return lca, depth, get_lca

