        ptr += 1
        s = input[ptr]
        ptr += 1
        edges = []
        for _ in range(n - 1):
            x = int(input[ptr]) - 1
            y = int(input[ptr + 1]) - 1
            ptr += 2
            edges.append((x, y))

        q = int(input[ptr])
        ptr += 1
        queries = []
        for _ in range(q):
            u = int(input[ptr]) - 1
            v = int(input[ptr + 1]) - 1
            ptr+= 2
            queries.append((u, v))

        lca, depth, get_lca = build_lca_tree(n, edges)

        def get_path_chars(start, end):
            path_chars = []
            while start != end:
                path_chars.append(s[start])
                start = parent[start]
            return path_chars

        parent = [-1] * n
        depth = [0] * n
        adj = [[] for _ in range(n)]

        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        def dfs(node, par, d):
            parent[node] = par
            depth[node] = d
            for child in adj[node]:
                if child != par:
                    dfs(child, node, d + 1)

        dfs(0, -1, 0)

        for u, v in queries:
            l = get_lca(u, v)

            path_u_to_l = get_path_chars(u, l)[::-1]
            path_v_to_l = get_path_chars(v, l)[::-1]

            combined = path_u_to_l + path_v_to_l

            freq = [0] * 26
            for char in combined:
                freq[ord(char) - ord('a')] += 1

            odd_count = sum(1 for count in freq if count % 2 == 1)

            if odd_count <= 1:
                results.append("YES")
            else:
                results.append("NO")

    print("\n".join(results))

if __name__ == "__main__":
    main()
